import * as React from 'react';
import { expect, it, vi } from 'vitest';
import { render, fireEvent, screen, act, cleanup } from '@testing-library/react';
import { Field } from '@base-ui/react/field';
import { Form } from '@base-ui/react/form';

const out: Record<string, unknown> = {};
afterEach(() => cleanup());
afterAll(() => {
  // eslint-disable-next-line no-console
  console.log('PROBE ' + JSON.stringify(out, null, 1));
});

function countRenders(mode: any, withForm = false, validate: any = () => null) {
  const counts = { control: 0, root: 0 };
  function App() {
    const [value, setValue] = React.useState('');
    const tree = (
      <Field.Root
        name="x"
        validationMode={mode}
        validate={validate}
        render={(props) => {
          counts.root += 1;
          return <div {...props} />;
        }}
      >
        <Field.Control
          data-testid="control"
          value={value}
          onValueChange={setValue}
          render={(props) => {
            counts.control += 1;
            return <input {...props} />;
          }}
        />
      </Field.Root>
    );
    return withForm ? <Form>{tree}</Form> : tree;
  }
  render(<App />);
  const control = screen.getByTestId('control');
  fireEvent.change(control, { target: { value: 'a' } });
  const settled = { ...counts };
  fireEvent.change(control, { target: { value: 'ab' } });
  fireEvent.change(control, { target: { value: 'abc' } });
  return { control: (counts.control - settled.control) / 2, root: (counts.root - settled.root) / 2 };
}

it('render counts', () => {
  out.rendersPerKeystroke_default = countRenders(undefined);
  cleanup();
  out.rendersPerKeystroke_onChange = countRenders('onChange');
  cleanup();
  out.rendersPerKeystroke_onChange_form = countRenders('onChange', true);
  cleanup();
  out.rendersPerKeystroke_onChange_invalid = countRenders('onChange', false, () => 'bad');
});

it('disabled while loading then enabled with loaded value (same commit)', () => {
  function App() {
    const [data, setData] = React.useState<string | null>(null);
    const [value, setValue] = React.useState('');
    return (
      <div>
        <Field.Root data-testid="root" disabled={data === null}>
          <Field.Control value={value} onValueChange={setValue} />
        </Field.Root>
        <button
          onClick={() => {
            setData('loaded');
            setValue('loaded');
          }}
        >
          load
        </button>
      </div>
    );
  }
  render(<App />);
  fireEvent.click(screen.getByRole('button'));
  const root = screen.getByTestId('root');
  out.loadSameCommit_dirty = root.hasAttribute('data-dirty');
  out.loadSameCommit_disabled = root.hasAttribute('data-disabled');
  // user types then returns
  const control = screen.getByRole('textbox');
  fireEvent.change(control, { target: { value: 'loadedx' } });
  fireEvent.change(control, { target: { value: 'loaded' } });
  out.loadSameCommit_dirtyAfterRoundTrip = root.hasAttribute('data-dirty');
});

it('value loads while disabled, enabled later', () => {
  function App() {
    const [disabled, setDisabled] = React.useState(true);
    const [value, setValue] = React.useState('');
    return (
      <div>
        <Field.Root data-testid="root" disabled={disabled}>
          <Field.Control value={value} onValueChange={setValue} />
        </Field.Root>
        <button onClick={() => setValue('loaded')}>load</button>
        <button onClick={() => setDisabled(false)}>enable</button>
      </div>
    );
  }
  render(<App />);
  fireEvent.click(screen.getByText('load'));
  fireEvent.click(screen.getByText('enable'));
  out.loadWhileDisabled_dirty = screen.getByTestId('root').hasAttribute('data-dirty');
});

it('plain async load, never disabled (by-design baseline)', () => {
  function App() {
    const [value, setValue] = React.useState('');
    return (
      <div>
        <Field.Root data-testid="root">
          <Field.Control value={value} onValueChange={setValue} />
        </Field.Root>
        <button onClick={() => setValue('loaded')}>load</button>
      </div>
    );
  }
  render(<App />);
  fireEvent.click(screen.getByText('load'));
  out.plainLoad_dirty = screen.getByTestId('root').hasAttribute('data-dirty');
});

it('unmount while focused', () => {
  function App() {
    const [show, setShow] = React.useState(true);
    return (
      <div>
        <Field.Root data-testid="root">
          {show ? <Field.Control /> : null}
        </Field.Root>
        <button onClick={() => setShow(false)}>hide</button>
      </div>
    );
  }
  render(<App />);
  const control = screen.getByRole('textbox');
  act(() => control.focus());
  const root = screen.getByTestId('root');
  out.unmount_focusedBefore = root.hasAttribute('data-focused');
  // click without moving focus (e.g. keyboard shortcut / programmatic)
  act(() => {
    screen.getByText('hide').dispatchEvent(new MouseEvent('click', { bubbles: true }));
  });
  out.unmount_focusedAfter = root.hasAttribute('data-focused');
});

it('disabled while focused', () => {
  function App() {
    const [disabled, setDisabled] = React.useState(false);
    return (
      <div>
        <Field.Root data-testid="root">
          <Field.Control disabled={disabled} />
        </Field.Root>
        <button onClick={() => setDisabled(true)}>disable</button>
      </div>
    );
  }
  render(<App />);
  const control = screen.getByRole('textbox');
  act(() => control.focus());
  const root = screen.getByTestId('root');
  act(() => {
    screen.getByText('disable').dispatchEvent(new MouseEvent('click', { bubbles: true }));
  });
  out.disable_focusedAfter = root.hasAttribute('data-focused');
});

it('async validator: programmatic change supersedes pending result', async () => {
  const resolvers: Array<(v: string | null) => void> = [];
  const validate = vi.fn(
    (v: unknown) => new Promise<string | null>((resolve) => resolvers.push(resolve)),
  );
  function App() {
    const [value, setValue] = React.useState('');
    return (
      <div>
        <Field.Root data-testid="root" validationMode="onChange" validate={validate}>
          <Field.Control value={value} onValueChange={setValue} />
          <Field.Error data-testid="error" />
        </Field.Root>
        <button onClick={() => setValue('')}>clear</button>
      </div>
    );
  }
  render(<App />);
  fireEvent.change(screen.getByRole('textbox'), { target: { value: 'bad' } });
  fireEvent.click(screen.getByText('clear'));
  await act(async () => {
    resolvers[0]('stale error for bad');
    await Promise.resolve();
  });
  await act(async () => {
    resolvers[1]?.(null);
    await Promise.resolve();
  });
  out.async_calls = validate.mock.calls.map((c) => c[0]);
  out.async_staleErrorShown = !!screen.queryByText('stale error for bad');
  out.async_invalid = screen.getByTestId('root').hasAttribute('data-invalid');
});

it('controlled: server error + value change in one batch', () => {
  function App() {
    const [errors, setErrors] = React.useState<Record<string, string>>({});
    const [value, setValue] = React.useState('abc ');
    return (
      <Form errors={errors}>
        <Field.Root name="x">
          <Field.Control value={value} onValueChange={setValue} />
          <Field.Error data-testid="error" />
        </Field.Root>
        <button
          type="button"
          onClick={() => {
            setErrors({ x: 'Server error' });
            setValue('abc');
          }}
        >
          go
        </button>
      </Form>
    );
  }
  render(<App />);
  fireEvent.click(screen.getByText('go'));
  out.batch_serverErrorShown = !!screen.queryByText('Server error');
});
