    <Field.Root validationMode="onChange" validate={validate} data-testid="root">
      <Field.Control type="checkbox" value="agree" required data-testid="c" />
    </Field.Root>,
  );
  const c = screen.getByTestId('c') as HTMLInputElement;
  fireEvent.click(c); await flush();
  const afterCheck = { checked: c.checked, calls: validate.mock.calls.length, invalid: c.getAttribute('aria-invalid') };
