  results.f1a = { afterCheck, afterUncheck: { checked: c.checked, calls: validate.mock.calls.length, invalid: c.getAttribute('aria-invalid'), rootInvalid: screen.getByTestId('root').hasAttribute('data-invalid') } };
});

it('f1b checkbox in form after failed submit', async () => {
  render(
    <Form>
      <Field.Root name="agree" data-testid="root">
        <Field.Control type="checkbox" value="agree" required data-testid="c" />
        <Field.Error data-testid="err" />
      </Field.Root>
      <button type="submit">submit</button>
    </Form>,
  );
  const c = screen.getByTestId('c') as HTMLInputElement;
  fireEvent.click(screen.getByText('submit')); await flush();
  const afterSubmit = { invalid: c.getAttribute('aria-invalid'), err: screen.queryByTestId('err')?.textContent ?? null };
  fireEvent.click(c); await flush();
  results.f1b = { afterSubmit, afterCheck: { checked: c.checked, invalid: c.getAttribute('aria-invalid'), err: screen.queryByTestId('err')?.textContent ?? null } };
