function countRenders(rootProps: Record<string, unknown>, opts: { submitFirst?: boolean } = {}) {
  const counter = { control: 0, root: 0 };
  function App() {
    const [value, setValue] = React.useState('');
    const tree = (
      <Field.Root
        {...rootProps}
        render={(props) => { counter.root += 1; return <div {...props} />; }}
      >
        <Field.Control
          data-testid="c"
          value={value}
          onValueChange={setValue}
          render={(props) => { counter.control += 1; return <input {...props} />; }}
        />
      </Field.Root>
    );
    return opts.submitFirst ? <Form>{tree}<button type="submit">submit</button></Form> : tree;
  }
  return { App, counter };
}

